    _fmt.restoreState(inFence: _savedFence, table: seed ?? const []);
    _pendingSeedTable = null;
    final outsPerLine = <List<String>>[];
    final fenceAfter = <bool>[];
    final tableBefore = <bool>[];
    final pendingStartAt = <int>[];
