  _srcFmtStarts.length = edge;
  _srcFmtStarts.add(_formatted.length);
  _srcRowStarts.length = edge;
  _srcRowStarts.add(_rows.length);
  _through = edge;
  _boundaryLast = edge > 0 ? src[edge - 1] : null;
