    final projectText = await _readTextOrNull(projectPath);
    if (projectText == null) {
      report.notes.add(
        'project config absent (defaults apply): $projectPath',
      );
    } else {
      final projectWarnings = <ConfigDiagnostic>[];
      _collectDiagnostics(
        projectText,
        projectPath,
        report.errors,
        projectWarnings,
      );
      report.warnings.addAll(projectWarnings);
      // Dead config: sections the project file is never read for.
      final doc = _tryParse(projectText);
      if (doc != null) {
        for (final key in doc.keys) {
          if (!_projectSections.contains('$key')) {
            report.warnings.add(
