    final cells = [for (final row in rows) _splitCells(row)];
    final columnCount = cells.first.length;
    final uniform = cells.every((c) => c.length == columnCount);
    final hasSeparator =
        rows.length >= 2 &&
        cells[1].every((c) => _tableSeparatorCellRe.hasMatch(c));
