+  /// merges into the growing tail like a real streamed answer), checking
+  /// the incremental view against the one-shot pass at every step.
+  void expectParityUnderDeltas(
+    TranscriptMarkdown tx,
+    List<String> src,
+    List<String> fragments,
+    String note,
+  ) {
