  /// or a `--no-format`/`FA_NO_FORMAT` request renders raw; `NO_COLOR` /
  /// `TERM=dumb` on a TTY renders plain; a color terminal renders ANSI.
  factory MarkdownSurface.resolving({
    required bool tty,
    required bool color,
    bool format = true,
    int width = 80,
    ColorProfile? profile,
