  final boundary = _boundaryLast;
  if (boundary == null || _boundaryFirst == null) return false;
  if (src.isEmpty || !identical(src.first, _boundaryFirst)) return false;
  if (!_tailIsFaithfulGrowth(src, boundary)) {
