  // formatted line showed up in scroll/stream rendering profiles.
  static final _ruleRe = RegExp(r'^─+$');

  /// The SGR matcher shared with [wrapAnsiLine] and tests.
  static RegExp get ansiSgrPattern => _ansiRe;

